classical_mode = True


def is_classical():
    global classical_mode  # noqa: F824
    return classical_mode


def enable_cloud():
    global classical_mode
    classical_mode = False


class NoMatchingObjectsFoundException(Exception):
    """NoMatchingObjectsFoundException is raised when a query returns empty list of objects."""


class admin_operations(object):

    def _get_managed_objects(self, moc='NRBTS_A', remote_host=None):
        with get_admin_interface(remote_host=remote_host) as admin_client:
            return admin_client.get_managed_objects(moc)

    def _verify_object(self, object_name, moc, remote_host=None):
        """
        Search for the object
        :param object_name: While refering to objects, their number should be added to their moc path,
        to refer to NRCELL-1 use NRCELL_A-1
        :moc:
        """
        with get_admin_interface(remote_host=remote_host) as admin_client:
            infomodel_object = admin_client.get_managed_objects(moc)
            return any(object_name in item['distName'] for item in infomodel_object)

    def __search_for_NP_number(self, infomodel_object):
        return int(re.search(r'NP-(\d+)', infomodel_object['distName']).group(1))

    def get_parameters_for_latest_NP(self, infomodel_object):
        return max(infomodel_object, key=self.__search_for_NP_number)['parameters']

    def assert_equal(self, expected, actual, message=None):
        """
        Checks if 2 values are the same
        :param expected:
        :param actual:
        :param message:
        :return:
        """
        if not message:
            message = 'Given values did not match'
            if expected != actual:
                if type(expected) is type(actual):
                    message += '\nExpected: {}\n  Actual: {}'.format(expected, actual)
                else:
                    message += '\nExpected: {} {}\n  Actual: {} {}'.format(
                        expected, str(type(expected)), actual, str(type(actual))
                    )
                raise AssertionError(message)
        else:
            if expected != actual:
                raise AssertionError(message)

    def check_until_timeout(self, checking_func, timeout, check_interval=1, error_msg="", **kwargs):
        """
        Keeps checking given function until a timeout is reached
        :param checking_func:
        :param timeout:
        :param check_interval:
        :param kwargs:
        :return:
        """
        timeout = int(timeout)
        error = None
        start_time = time.time()
        while time.time() - start_time < timeout:
            try:
                checking_func(**kwargs)
                break
            except Exception as err:
                error = err
                time.sleep(check_interval)
                continue
        else:
            if error_msg:
                raise ExecutionFailed(error_msg)
            else:
                raise error

    def check_after_time_elapsed(self, checking_func, time_elapsed, error_msg="", **kwargs):
        """
        Runs a function after given time has passed
        :param checking_func:
        :param time_elapsed:
        :param error_msg:
        :param kwargs:
        :return:
        """
        time.sleep(time_elapsed)
        try:
            checking_func(**kwargs)
        except Exception as e:
            if error_msg:
                raise ExecutionFailed(error_msg)
            else:
                raise e

    def check_in_time_interval(self, checking_func, time_min, time_max, check_interval=1, **kwargs):
        """
        Keep checking the function until time max but after time_min has passed
        :param check_interval:
        :param checking_func:
        :param time_min:
        :param time_max:
        :param kwargs:
        :return:
        """
        time.sleep(time_min)
        self.check_until_timeout(checking_func=checking_func, timeout=time_max, check_interval=check_interval, **kwargs)

    def get_managed_object(self, object_name, moc='NRBTS_A'):
        managed_objects = self._get_managed_objects(moc)
        for managed_object in managed_objects:
            if managed_object['distName'].endswith(object_name):
                return managed_object['parameters']

        raise Exception('Object {} not found'.format(object_name))

    def get_configuration_parameter_value(self, parameter_name, moc_path='NRBTS_A'):
        infomodel_object = self._get_managed_objects(moc_path)
        parameters = self.get_parameters_for_latest_NP(infomodel_object)
        return parameters[parameter_name]

    def get_admin_object_parameter_value(self, parameter_name, moc='NRBTS_A'):
        infomodel_object = self._get_managed_objects(moc)
        return infomodel_object[0]['parameters'][parameter_name]

    def get_admin_object_parameter_value_from_sorted_list(self, parameter_name, moc='NRBTS_A', index=0):
        infomodel_object = sorted(self._get_managed_objects(moc),
                                  key=lambda x: x['distName'])
        return infomodel_object[index]['parameters'][parameter_name]

    def get_number_of_defined_objects(self, moc='NRBTS_A', remote_host=None):
        infomodel_object = self._get_managed_objects(moc, remote_host=remote_host)
        return len(infomodel_object)

    def check_configuration_parameter_value(self, name, value):
        logger.info("Checking if parameter {} has value {}.".format(name, value), also_console=True)
        self.assert_equal(expected=value, actual=self.get_configuration_parameter_value(name))

    def check_admin_object_parameter_value(self, parameter_name, value, moc='NRBTS_A'):
        logger.info("Checking if parameter {} has value {}.".format(parameter_name, value), also_console=True)
        self.assert_equal(expected=str(value), actual=str(self.get_admin_object_parameter_value(parameter_name, moc)))

    def get_parameter_values_for_objects(self, object_types, mocs, parameter):  # noqa: C901
        values_dictionary = {}
        for moc in mocs:
            managed_object = self._get_managed_objects(moc)
            if managed_object is None:
                continue
            for object_type in object_types:
                for n in range(len(managed_object)):
                    try:
                        distName = managed_object[n]['distName']
                        if object_type in distName:
                            values_dictionary[distName] = managed_object[n]['parameters'][parameter]
                    except KeyError:
                        continue
        return values_dictionary

    def check_admin_object_parameter_value_from_list(self, parameter_name, value, index, moc='NRBTS_A',
                                                     log_to_console=True):
        logger.info("Check if parameter {} at moc {} has value {}.".format(parameter_name, moc + "-{}".format(
            int(index) + 1), value), also_console=log_to_console)
        actual = self.get_admin_object_parameter_value_from_sorted_list(parameter_name=parameter_name,
                                                                        moc=moc, index=int(index))
        self.assert_equal(expected=str(value), actual=str(actual))

    def get_admin_object_parameter_value_aic(self, dist_name, parameter_name):
        with self.connect_to_vcu_aic() as vcu_connection:
            parameters = vcu_connection.get_parameters(dist_name)
        for element in parameters['parameters']:
            try:
                if element['simple_parameter'].name == parameter_name:
                    logger.console("Value of {} is {}".format(parameter_name, element['simple_parameter'].value))
                    return element['simple_parameter'].value
            except AttributeError:
                continue

    def get_admin_object_parameter_value_vdu_aic(self, dist_name, parameter_name, vdu=1):
        tl = BuiltIn().get_variable_value("${tl}")
        host = tl.gnbs[0].dus[int(vdu) - 1].oam_http_connection_details.addr
        with self.connect_to_vdu_aic(host) as vdu_connection:
            parameters = vdu_connection.get_managed_object_parameters_of_current_plan(dist_name)
        for element in parameters['parameters']:
            if element['simple_parameter'].get('name') == parameter_name:
                logger.console("Value of {} is {}".format(parameter_name, element['simple_parameter']['value']))
                return element['simple_parameter']['value']

    def check_admin_object_parameter_value_aic(self, dist_name, parameter_name, expected_state):
        actual = self.get_admin_object_parameter_value_aic(dist_name, parameter_name)
        self.assert_equal(expected=expected_state.lower(), actual=actual.lower(),
                          message="Parameter {} is {}\n {} should be {}".format(parameter_name, actual, parameter_name, expected_state))

    def check_admin_object_parameter_value_vdu_aic(self, dist_name, parameter_name, expected_state, vdu=1):
        actual = self.get_admin_object_parameter_value_vdu_aic(dist_name, parameter_name, vdu=vdu)
        self.assert_equal(expected=expected_state.lower(), actual=actual.lower(),
                          message="Parameter {} is {}\n {} should be {}".format(parameter_name, actual, parameter_name, expected_state))

    def wait_for_object_to_exist_aic(self, dist_name, timeout=600):
        logger.console("Waiting {} seconds for object {} to exist.".format(timeout, dist_name))
        timeout = int(timeout)
        while timeout > 0:
            time.sleep(1)
            timeout -= 1
            try:
                with self.connect_to_vcu_aic() as vcu_connection:
                    vcu_connection.get_parameters(dist_name)
                    logger.console('MOC {} is now available'.format(dist_name))
                    break
            except Exception:
                continue
        else:
            raise Exception('MOC {} is not available after {} seconds'.format(dist_name, timeout))

    def wait_for_parameter_value_change(self, parameter_name, value, moc='NRBTS_A', timeout=1100, index=0):
        logger.info("Waiting {} seconds for parameter {} at moc {} to change value for {}.".format(
            timeout, parameter_name, moc + "-{}".format(int(index) + 1), value), also_console=True)
        self.check_until_timeout(
            checking_func=self.check_admin_object_parameter_value_from_list,
            timeout=timeout,
            parameter_name=parameter_name,
            value=value,
            index=int(index),
            moc=moc,
            log_to_console=False
        )

    def check_if_object_exists(self, object_name, moc='NRCELL_A', log_to_console=True):
        logger.info("Checking if object {} exists.".format(object_name), also_console=log_to_console)
        does_exist = self._verify_object(object_name=object_name, moc=moc)
        self.assert_equal(actual=does_exist, expected=True)

    def check_if_object_doesnt_exist(self, object_name, moc='NRCELL_A', log_to_console=True):
        logger.info("Checking if object {} doesn't exist.".format(object_name), also_console=log_to_console)
        does_exist = self._verify_object(object_name=object_name, moc=moc)
        self.assert_equal(actual=does_exist, expected=False)

    def wait_for_object_to_exist(self, object_name, moc='NRCELL_A', timeout=30):
        logger.info("Waiting {} seconds for object {} to exist.".format(timeout, object_name), also_console=True)
        self.check_until_timeout(self.check_if_object_exists, timeout=timeout, object_name=object_name, moc=moc,
                                 log_to_console=False)

    def wait_for_object_to_not_exist(self, object_name, moc='NRCELL_A', timeout=30):
        logger.info("Waiting {} seconds for object {} to not exist.".format(timeout, object_name), also_console=True)
        self.check_until_timeout(self.check_if_object_doesnt_exist, timeout=timeout, object_name=object_name, moc=moc,
                                 log_to_console=False)

    def wait_for_object_to_appear(self, time_elapsed, object_name, moc='NRCELL_A'):
        """
        Difference between wait_for_object_to_appear and wait_for_object_to_exist is that wait_for_object_to_exist
        checks if object exists in any time before timeout where wait_for_object_to_appear checks existence after
        time_elapsed.
        :param time_elapsed:
        :param object_name:
        :param moc:
        :return:
        """
        logger.info("Check if object {} has appeared in {} seconds.".format(object_name, time_elapsed), also_console=True)
        self.check_after_time_elapsed(checking_func=self.check_if_object_exists, time_elapsed=time_elapsed,
                                      object_name=object_name, moc=moc, log_to_console=False)

    def wait_for_object_to_not_appear(self, time_elapsed, object_name, moc='NRCELL_A'):
        logger.info("Check if object {} has not appeared in {} seconds.".format(object_name, time_elapsed),
                    also_console=True)
        self.check_after_time_elapsed(checking_func=self.check_if_object_doesnt_exist, time_elapsed=time_elapsed,
                                      object_name=object_name, moc=moc, log_to_console=False)

    def find_object_in_time_interval(self, object_name, time_min=15, time_max=60, moc='NRCELL_A'):
        self.check_in_time_interval(checking_func=self.check_if_object_exists, time_min=time_min, time_max=time_max,
                                    object_name=object_name, moc=moc, log_to_console=False)

    def dont_find_object_in_time_interval(self, object_name, time_min=15, time_max=60, moc='NRCELL_A'):
        self.check_in_time_interval(checking_func=self.check_if_object_doesnt_exist, time_min=time_min,
                                    time_max=time_max, object_name=object_name, moc=moc, log_to_console=False)

    def get_xnlinkstatus_parameter_value(self, xn_link_id, value):
        infomodel_object = sorted(self._get_managed_objects('XNLINK_R'),
                                  key=lambda x: x['distName'])
        for xn in infomodel_object:
            if 'XNLINK_R-{}'.format(xn_link_id) in xn['distName']:
                actual = xn['parameters']['xnLinkStatus']
                self.assert_equal(expected=str(value), actual=str(actual))
                break
        else:
            raise Exception('Object XNLINK-{} not found'.format(xn_link_id))

    def wait_for_xn_link_status_value_change(self, xn_link_id, value, timeout=1100):
        logger.info("Waiting {} seconds for parameter xnLinkStatus at moc XNLINK-{} to change value for {}.".format(
            timeout, xn_link_id, value), also_console=True)
        self.check_until_timeout(
            checking_func=self.get_xnlinkstatus_parameter_value,
            timeout=timeout,
            xn_link_id=xn_link_id,
            value=value)

    def check_if_f1_links_available_aic(self):
        with self.connect_to_vcu_aic() as vcu_connection:
            vdu_state = vcu_connection.get_du_state()
            number_of_unavailable_f1_links = vdu_state['f1_link_status']['unavailable']
            if number_of_unavailable_f1_links > 0:
                logger.console("{} f1_link_status is set to unavailable".format(number_of_unavailable_f1_links))
                raise Exception
            logger.console("F1 link available")

    def get_state_of_f1_link_aic(self, vdu=1):
        with self.connect_to_vcu_aic() as vcu_connection:
            vdu_state = vcu_connection.get_du(du_id=str(vdu))['f1_link_status']
            f1_link = vdu_state['f1_link_status']
            logger.console(f1_link)
            return f1_link

    def wait_for_f1_links_to_be_available_aic(self, timeout=300):
        logger.info("Waiting {} seconds for parameter f1 links to be available".format(
                    timeout), also_console=True)
        self.check_until_timeout(checking_func=self.check_if_f1_links_available_aic, timeout=timeout)

    def get_x2_link_info_aic(self):
        """
        Keyword for getting info regarding x2 link in aic
        return: dict with info about created, removed and updated X2 links
        """
        with self.connect_to_vcu_aic() as vcu_connection:
            x2_link_info = vcu_connection.get_x2_links_info()
            return x2_link_info

    def get_xn_link_status_aic(self):
        """
        Keyword for getting info regarding xn link in aic
        return: dict with info about created, removed and updated Xn links
        """
        with self.connect_to_vcu_aic() as vcu_connection:
            xn_link_info = vcu_connection.get_xn_link_status()
            return xn_link_info

    def get_ng_link_status_aic(self):
        """
        Keyword for getting info regarding ng link in aic
        return: dict with info about created, removed and updated ng links
        """
        with self.connect_to_vcu_aic() as vcu_connection:
            ng_link_info = vcu_connection.get_ng_links_info()
            return ng_link_info

    def check_if_ng_link_is_active_aic(self):
        ng_link_info = self.get_ng_link_status_aic()
        ng_link_status = ng_link_info[0]['ng_link_status']
        if ng_link_status.lower() != 'active':
            logger.console("ng_link_status is set to {}".format(ng_link_status))
            raise Exception
        logger.console("Ng link is active")

    def wait_for_ng_link_to_be_active_aic(self, timeout=300):
        logger.info("Waiting {} seconds for parameter ng link to be active".format(
                    timeout), also_console=True)
        self.check_until_timeout(checking_func=self.check_if_ng_link_is_active_aic, timeout=timeout)

    def get_number_of_vdu(self):
        with self.connect_to_vcu_aic() as vcu_connection:
            vdu_state = vcu_connection.get_du_state()
            number_of_vdu = vdu_state['f1_link_status']['available']
            return number_of_vdu

    @contextmanager  # noqa: C901
    def connect_to_vcu_aic(self, host=None, port='443', username='Nemuadmin', password='Nokia@123',
                           cu_version='cuoam_25r2', secure=True, login_disabled=False, alias=None, timeout=None):
        """
        Provides connection to vCU

        """
        if host is None:
            try:
                tl = BuiltIn().get_variable_value("${tl}")
                host = tl.gnbs[0].cu.oam_http_connection_details.addr
            except Exception:
                host = '192.168.100.129'
        number_of_tries = 10
        while number_of_tries > 0:
            try:
                cu_object = cu()
                cu_object.connect_to(host, port, username, password, cu_version,
                                     secure, login_disabled, alias, timeout)
                break
            except Exception:
                logger.info('Waiting for connection to vCU', also_console=True)
                time.sleep(60)
                number_of_tries -= 1
        try:
            yield cu_object
        finally:
            cu_object.disconnect()

    @contextmanager  # noqa: C901
    def connect_to_vdu_aic(self, host=None, port=443, username='Nemuadmin', password='Nokia@123',
                           vdu_version='cuoam_25r2', secure=True, login_disabled=False, connection_name="default",
                           need_all_info=False, vdu_to_connect=1):
        """
        Provides connection to vDU

        """
        if host is None:
            try:
                tl = BuiltIn().get_variable_value("${tl}")
                host = tl.gnbs[0].dus[int(vdu_to_connect) - 1].oam_http_connection_details.addr
            except Exception:
                host = '192.168.255.129'
        number_of_tries = 10
        while number_of_tries > 0:
            try:
                vdu_object = vdu()
                vdu_object.connect_to(host, port, username, password, vdu_version, secure,
                                      login_disabled, connection_name, need_all_info)
                break
            except Exception:
                logger.info('Waiting for connection to vDU', also_console=True)
                time.sleep(60)
                number_of_tries -= 1
        try:
            yield vdu_object
        finally:
            vdu_object.disconnect()

    def is_classical(self):
        return is_classical()

    def enable_cloud(self):
        enable_cloud()


class ssh:

    def __init__(self, address, username, password):
        self.client = paramiko.SSHClient()
        self.client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.client.connect(address, username=username, password=password, look_for_keys=False)
        channel = self.client.invoke_shell()
        self.stdin = channel.makefile('wb')
        self.stdout = channel.makefile('r')

    def close_connection(self):
        if (self.client is not None):
            self.client.close()

    def send_shell_command(self, command):  # noqa: C901
        command = command.strip('\n')
        self.stdin.write(command + '\n')
        finish = 'end of stdOUT buffer. finished with exit status'
        echo_command = 'echo {} $?'.format(finish)
        self.stdin.write(echo_command + '\n')
        shin = self.stdin
        self.stdin.flush()
        shout = []
        sherr = []

        for line in self.stdout:
            str_line = re.compile(r'(\x9B|\x1B\[)[0-?]*[ -/]*[@-~]').sub('', line).replace('\b', '').replace('\r', '')
            if str_line.startswith(command) or str_line.startswith(echo_command):
                pass
            elif str_line.startswith(finish):
                break
            elif 'error' in str_line:
                sherr.append(str_line.strip('\n'))
            else:
                shout.append(str_line)

        if shout and echo_command in shout[-1]:
            shout.pop()
        if shout and command in shout[0]:
            shout.pop(0)
        return shin, shout, sherr


@contextmanager
def create_shell_session_vcu(host='10.84.134.2', user='core', password='system123'):
    """
    Creates shell session with vCU

    """
    handler = ssh(host, user, password)
    try:
        yield handler
    finally:
        handler.close_connection()


def execute_command_on_remote_host(
    vm_ip=None,
    vm_username='ute',
    vm_password='ute',
    gnb_ip=None,
    gnb_username='toor4nsn',
    gnb_password='oZPS0POrRieRtu',
    command_to_execute=None,
    timeout=30
):
    vm_ssh_client = paramiko.SSHClient()
    vm_ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    gnb_ssh_client = paramiko.SSHClient()
    gnb_ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    command_output = ""
    vm_connected = False
    gnb_connected = False

    try:
        vm_ssh_client.connect(hostname=vm_ip, username=vm_username, password=vm_password, timeout=timeout)
        vm_connected = True
        vm_transport = vm_ssh_client.get_transport()
        dest_addr = (gnb_ip, 22)
        local_addr = ('localhost', 0)
        vm_channel = vm_transport.open_channel('direct-tcpip', dest_addr, local_addr)
        gnb_ssh_client.connect(hostname=gnb_ip, username=gnb_username, password=gnb_password, sock=vm_channel, timeout=timeout)
        gnb_connected = True
        stdin, stdout, stderr = gnb_ssh_client.exec_command(command_to_execute)
        command_output = stdout.read().decode('utf-8', errors='ignore').strip()

    except paramiko.AuthenticationException:
        logger.console("Authentication failed. Please check your usernames and passwords.")
    except paramiko.SSHException as e:
        logger.console("Error: SSH connection failed: {}".format(e))
    except Exception as e:
        logger.console("Error: An unexpected error occurred: {}".format(e))

    finally:
        if gnb_connected:
            gnb_ssh_client.close()
        if vm_connected:
            vm_ssh_client.close()

    return command_output


def download_file_from_remote_host(  # noqa: C901
    vm_ip=None, vm_username='ute', vm_password='ute',
    gnb_ip=None, gnb_username='toor4nsn', gnb_password='oZPS0POrRieRtu',
    source_path_on_gnb=None,
    destination_path_local=None,
):
    vm_ssh_client = None
    gnb_ssh_client = None
    sftp_client = None
    vm_channel = None

    try:
        vm_ssh_client = paramiko.SSHClient()
        vm_ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        vm_ssh_client.connect(hostname=vm_ip, username=vm_username, password=vm_password)
        vm_channel = vm_ssh_client.get_transport().open_channel(
            "direct-tcpip",
            (gnb_ip, 22),
            (vm_ip, 22)
        )
        gnb_ssh_client = paramiko.SSHClient()
        gnb_ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        gnb_ssh_client.connect(hostname=gnb_ip, username=gnb_username, password=gnb_password, sock=vm_channel)

        os.makedirs(destination_path_local, exist_ok=True)

        filename = os.path.basename(source_path_on_gnb)

        destination_file_path_local = os.path.join(destination_path_local, filename)

        sftp_client = gnb_ssh_client.open_sftp()
        sftp_client.get(source_path_on_gnb, destination_file_path_local)
        sftp_client = gnb_ssh_client.open_sftp()
        sftp_client.get(source_path_on_gnb, destination_path_local)

    except paramiko.AuthenticationException:
        logger.console("Authentication failed. Please check your usernames and passwords.")
    except FileNotFoundError:
        logger.console("Error: Source file {} not found on gNB or destination path invalid.".format(source_path_on_gnb))
    except paramiko.SSHException as e:
        logger.console("Error: SSH connection failed: {}".format(e))
    except Exception as e:
        logger.console("Error: An unexpected error occurred: {}".format(e))
    finally:
        if sftp_client:
            sftp_client.close()
        if gnb_ssh_client:
            gnb_ssh_client.close()
        if vm_ssh_client:
            vm_ssh_client.close()
        if vm_channel:
            vm_channel.close()
